(function(){
  // Local loader for Chart.js: if Chart is already present do nothing, otherwise load from CDN
  if (typeof window.Chart !== 'undefined') return;
  var s = document.createElement('script');
  s.src = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js';
  s.onload = function(){ console.info('Chart.js loaded'); };
  s.onerror = function(){ console.warn('Failed to load Chart.js from CDN'); };
  document.head.appendChild(s);
})();

